    code: "// Slider arrastável + ReconfigButton — a prova viva do mecanismo de ponteiro\n// (UIW005) e da vinculação pós-criação (UIW001). No browser (KofJS) o gesto é\n// real: arraste sobre o card move o polegar, clique no botão troca o rótulo.\nmain() {\n    var w = App(\"Slider e ReconfigButton\")\n    var vol = Slider(\"Volume\", 0, 100, 5, 20)\n    var power = ReconfigButton(\"LIGADO\", \"desligado\", 1)\n    w.bind(vol)\n    w.bind(power)\n    w.show()\n}\n",
